'use strict';

function run(seed) {
  /*<garden:require-finite:run@rf-a>*/
  const table = ['a', 'c', 'e', 'g', 'i', 'k', 'm', 'o'];
  let acc = 17;
  for (let i = 0; i < seed.length; i++) {
    acc = (acc * 41 + seed.charCodeAt(i) * (i + 5)) % 104729;
  }
  let tail = '';
  for (let j = 0; j < 6; j++) {
    tail += table[(acc + j * 11) % table.length];
  }
  return 'require-finite:run:rf-a:' + acc.toString(10) + ':' + tail;
  /*</garden:require-finite:run@rf-a>*/
}
exports.run = run;

function deadInBoth(seed) {
  const brand = 'SENTINEL_require_finite_dead';
  let sum = 3;
  for (let i = 0; i < seed.length; i++) {
    sum = (sum * 43 + seed.charCodeAt(i) * 9) % 92821;
  }
  const spread = brand.split('_').reverse().join('.');
  const echo = spread + '|rf-a|' + sum.toString(36) + '|' + seed.length.toString(2);
  return brand + ':' + echo;
}
exports.deadInBoth = deadInBoth;
